from lib import *
S = SS('f85')
R = J('f85'); md = R['modes']; op = R['opts']
steps = [
    step("默认 lazy='select':取出 1 个 Author 只发 1 条 SQL;第一次访问 a.books 才发 SELECT book.id, book.title, book.author_id FROM book WHERE ? = book.author_id;之后再访问两次新增 0 条(结果缓存在对象上)。多对一的 b.author:Author 1 已经在这个 session 的身份映射里时,0 条 SQL;清空 session 后再取,发 1 条 SELECT author ... WHERE author.id = ?。", t=tl(S(1)), done=lidx(S(1), '取出 1 个', '再访问'), mark=lidx(S(1), '第一次访问', '清空 session'), kv=KV([['默认 lazy', '访问时才发 SQL'], ['缓存', '对象上缓存,第二次不发'], ['多对一', '先看身份映射']], ['默认 lazy'])),
    step(f"取 10 个作者并遍历每人 5 本书各发多少 SQL:select {md['select'][0]} 条(1 + 10)、joined {md['joined'][0]} 条(一条 JOIN)、subquery {md['subquery'][0]} 条、selectin {md['selectin'][0]} 条、immediate {md['immediate'][0]} 条(加载作者后立即逐个发);raise 访问 books 抛 InvalidRequestError「'Author.books' is not available due to lazy='raise'」;noload 访问到 0 本(而且这个策略在 SQLAlchemy 2.1.1 里已被标为弃用)。", b=bars([['select', md['select'][0], str(md['select'][0])], ['joined', md['joined'][0], str(md['joined'][0])], ['subquery', md['subquery'][0], str(md['subquery'][0])], ['selectin', md['selectin'][0], str(md['selectin'][0])]], 11, mark=[0], done=[1, 2, 3]), t=tl(S(2)), done=lidx(S(2), 'joined', 'subquery', 'selectin'), mark=lidx(S(2), 'select ', 'immediate', 'raise'), kv=KV([['select / immediate', '1 + N 条'], ['joined', '1 条 JOIN'], ['subquery / selectin', '2 条']], ['joined'])),
    step(f"查询时用 options() 临时覆盖(模型上仍是默认 lazy='select'):不加 options {op['不加 options'][0]} 条;joinedload {op['joinedload'][0]} 条;selectinload {op['selectinload'][0]} 条;subqueryload {op['subqueryload'][0]} 条;raiseload 1 条,遍历 books 抛 InvalidRequestError。遍历到的书都是 50 本。", t=tl(S(3)), done=lidx(S(3), 'joinedload', 'selectinload', 'subqueryload'), mark=lidx(S(3), 'raiseload'), kv=KV([['options(...)', '按查询覆盖加载策略'], ['raiseload', '遗漏的 eager 加载立刻报错']], ['options(...)'])),
    step("对象 detached 之后读没加载的 a.books 抛 DetachedInstanceError;用 raiseload 加载的对象读 a.books 抛 InvalidRequestError(消息「'Author.books' is not available due to lazy='raise'」)。两种错都是「没有在查询时加载」,但 raiseload 在对象还在 session 里时就报,不用等到它离开 session;开发期用 raiseload 能把漏掉的 eager 加载提前暴露。", t=tl(S(4)), mark=lidx(S(4), 'DetachedInstanceError', 'raiseload'), kv=KV([['detached', 'DetachedInstanceError'], ['raiseload', 'InvalidRequestError']], ['raiseload'])),
    step("lazy='dynamic':a.books 变成 AppenderQuery,可以继续 filter(过滤后只取到 b0-1,发 1 条 SQL);每次访问都发 SQL,连续 count() 两次发 2 条,没有缓存。适合很大的集合,不适合要整体遍历的场景。", t=tl(S(5)), done=lidx(S(5), 'AppenderQuery', '继续过滤'), mark=lidx(S(5), 'count()'), kv=KV([['dynamic', '返回可过滤的查询'], ['缓存', '没有,每次发 SQL']], ['dynamic'])),
]
A = mkartf('f85', 85, 'Flask,SQLAlchemy,懒加载,eager loading,relationship,真实验证,动画演示',
    f'实测 SQLAlchemy 关系的加载策略:默认 lazy=select 访问时才发 SQL 并缓存;取 10 个作者遍历 50 本书,select {md["select"][0]} 条、joined {md["joined"][0]} 条、selectin {md["selectin"][0]} 条;options() 覆盖;raiseload 与 DetachedInstanceError;lazy=dynamic 返回可过滤的查询。',
    '访问 author.books 的那一刻到底发生了什么?各种 lazy 策略发多少条 SQL?什么时候该用 eager loading?这篇用 SQL 事件把每种策略发出的语句一条一条数出来。',
    [(f'{md["select"][0]} → {md["joined"][0]}', '遍历 10 个作者的书:lazy=select 与 joined 的 SQL 条数'), ('0 条', '多对一的目标对象已在身份映射里时,访问它发出的 SQL 条数'), ('raiseload', '漏掉 eager 加载时立刻报 InvalidRequestError')],
    [('默认的懒加载', '<p>上一篇:<a href="flask-model-table-mapping.html">Model 与 Table 映射</a>;下一篇:<a href="flask-joinedload-selectinload.html">joinedload() 与 selectinload()</a>。</p>'), ('各种 lazy 策略的 SQL 条数', None), ('options() 覆盖', None), ('detached 与 raiseload', None), ('lazy=dynamic', None)],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、SQLite(内存库)', '没有验证:PostgreSQL 上的相同对比(第 87 篇的 N+1 会用 PG 量耗时)、lazy=write_only、大集合下 joined 与 selectin 的内存与耗时差别(第 86 篇)、多层嵌套关系的加载'], 'Lazy 与 Eager Loading', panels=[('t', 'term', '实验输出'), ('b', 'bars', 'SQL 条数'), ('kv', 'kv', '要点')])
